#!/usr/bin/env python3"""Generate complete Android project for Heroes Lore Zero J2ME port."""import os, shutilBASE = "/home/z/my-project/java-emu-android/AndroidProject"APP = f"{BASE}/app/src/main"def w(path, content):    full = os.path.join(BASE, path)    os.makedirs(os.path.dirname(full), exist_ok=True)    with open(full, "w", encoding="utf-8") as f:        f.write(content)    print(f"  wrote {path}")# ============================================================# 1. Root build.gradle# ============================================================w("build.gradle", '''\nextbuildscript {    repositories {        google()        mavenCentral()    }    dependencies {        classpath \'com.android.tools.build:gradle:8.2.0\'    }}allprojects {    repositories {        google()        mavenCentral()    }}task clean(type: Delete) {    delete rootProject.buildDir}''')# ============================================================# 2. settings.gradle# ============================================================w("settings.gradle", '''\nrootProject.name = \'HeroesLoreZero\'include \\:app\'  ''')# ============================================================# 3. gradle.properties# ============================================================w("gradle.properties", '''\nandroid.useAndroidX=trueorg.gradle.jvmargs=-Xmx2048m''')# ============================================================# 4. app/build.gradle# ============================================================w("app/build.gradle", '''\nplugins {    id \'com.android.application\'}android {    namespace \'com.heroeslore.android\'    compileSdk 34    defaultConfig {        applicationId "com.heroeslore.android"        minSdk 21        targetSdk 34        versionCode 1        versionName "1.0"    }    buildTypes {        release {            minifyEnabled false            proguardFiles getDefaultProguardFile(\'proguard-android-optimize.txt\'), \'proguard-rules.pro\'        }    }    sourceSets {        main {            java.srcDirs = [\'src/main/java\']            assets.srcDirs = [\'src/main/assets\']        }    }    compileOptions {        sourceCompatibility JavaVersion.VERSION_1_8        targetCompatibility JavaVersion.VERSION_1_8    }}dependencies {    implementation \'androidx.appcompat:appcompat:1.6.1\'}''')# ============================================================# 5. gradle-wrapper.properties# ============================================================w("gradle/wrapper/gradle-wrapper.properties", '''\ndistributionBase=GRADLE_USER_HOMEdistributionPath=wrapper/distsdistributionUrl=https\\://services.gradle.org/distributions/gradle-8.5-bin.zipzipStoreBase=GRADLE_USER_HOMEzipStorePath=wrapper/dists''')# ============================================================# 6. AndroidManifest.xml# ============================================================w("app/src/main/AndroidManifest.xml", '''\n<?xml version="1.0" encoding="utf-8"?><manifest xmlns:android="http://schemas.android.com/apk/res/android">    <uses-permission android:name="android.permission.VIBRATE" />    <application        android:allowBackup="true"        android:icon="@mipmap/ic_launcher"        android:label="Heroes Lore Zero"        android:theme="@style/Theme.FullScreen.Landscape"        android:screenOrientation="sensorLandscape"        android:configChanges="orientation|screenSize|keyboardHidden">        <activity            android:name=".GameActivity"            android:exported="true"            android:screenOrientation="sensorLandscape"            android:configChanges="orientation|screenSize|keyboardHidden"            android:immersive="true">            <intent-filter>                <action android:name="android.intent.action.MAIN" />                <category android:name="android.intent.category.LAUNCHER" />            </intent-filter>        </activity>    </application></manifest>''')# ============================================================# 7. proguard-rules.pro# =================================